-- =====================================================================
-- P3 QMS 2부 Q8b 봉쇄 — 같은 품목·기간 LOT 일괄 보류 (docs/29_P3 12.8) — 임시 번호, 병합 때 재번호
--
-- - qms_contain: 봉쇄 한 건(품목·LOT 발생 기간·근거 NCR(선택, 같은 품목)·사유), OPEN → CLOSED(모든 LOT 해제). 삭제 금지
-- - qms_contain_lot: 봉쇄 × LOT, 해제(시각·사람·사유)는 한 번만. 삭제 금지
-- - LOT 보류·해제는 MES 계약 LotHoldPort 로만(출처 QMS_CONTAIN, 참조 = contain_id), LOT 여럿은 lot_id 오름차순.
--   contain_id 는 시퀀스에서 먼저 받는다(GENERATED BY DEFAULT — 잠금 순서 LOT → qms_contain, Q8a 와 같은 이유)
-- =====================================================================

INSERT INTO sys_code_grp (grp_cd, grp_nm_key, comp_ext_yn) VALUES
    ('QMS_CONTAIN_STATUS', 'code.grp.QMS_CONTAIN_STATUS', 'N');
INSERT INTO sys_code (grp_cd, code, code_nm_key, sort_no) VALUES
    ('QMS_CONTAIN_STATUS', 'OPEN',   'code.QMS_CONTAIN_STATUS.OPEN',   1),
    ('QMS_CONTAIN_STATUS', 'CLOSED', 'code.QMS_CONTAIN_STATUS.CLOSED', 2);

CREATE TABLE qms_contain (
    contain_id    bigint          GENERATED BY DEFAULT AS IDENTITY,
    comp_cd       varchar(20)     NOT NULL,
    contain_no    varchar(30)     NOT NULL,
    item_id       bigint          NOT NULL,
    ncr_id        bigint,
    from_date     date            NOT NULL,
    to_date       date            NOT NULL,
    reason        varchar(500)    NOT NULL,
    status        varchar(6)      NOT NULL DEFAULT 'OPEN',
    lot_cnt       integer         NOT NULL,
    closed_at     timestamptz,
    row_ver       integer         NOT NULL DEFAULT 0,
    created_at    timestamptz     NOT NULL DEFAULT now(),
    created_by    varchar(50)     NOT NULL,
    updated_at    timestamptz     NOT NULL DEFAULT now(),
    updated_by    varchar(50)     NOT NULL,
    CONSTRAINT pk_qms_contain PRIMARY KEY (contain_id),
    CONSTRAINT fk_qms_contain_comp FOREIGN KEY (comp_cd) REFERENCES sys_comp (comp_cd),
    CONSTRAINT fk_qms_contain_item FOREIGN KEY (item_id) REFERENCES mst_item (item_id),
    CONSTRAINT fk_qms_contain_ncr FOREIGN KEY (ncr_id) REFERENCES qms_ncr (ncr_id),
    CONSTRAINT uq_qms_contain_no UNIQUE (comp_cd, contain_no),
    CONSTRAINT ck_qms_contain_dates CHECK (from_date <= to_date),
    CONSTRAINT ck_qms_contain_reason CHECK (length(btrim(reason)) > 0),
    CONSTRAINT ck_qms_contain_status CHECK (status IN ('OPEN', 'CLOSED')),
    CONSTRAINT ck_qms_contain_lot_cnt CHECK (lot_cnt BETWEEN 1 AND 500),
    CONSTRAINT ck_qms_contain_closed CHECK ((status = 'CLOSED') = (closed_at IS NOT NULL))
);
CREATE INDEX ix_qms_contain_created ON qms_contain (comp_cd, created_at DESC);
CREATE INDEX ix_qms_contain_ncr ON qms_contain (ncr_id) WHERE ncr_id IS NOT NULL;
COMMENT ON TABLE qms_contain IS '봉쇄 — 같은 품목·기간 의심 LOT 일괄 보류(사람이 고름), OPEN → CLOSED(모든 LOT 해제) (docs/29_P3 Q8b)';
COMMENT ON COLUMN qms_contain.contain_id IS 'GENERATED BY DEFAULT — 서비스가 시퀀스에서 먼저 받아 LOT 보류(포트, lot_id 오름차순) 뒤 INSERT';

CREATE FUNCTION hb_guard_qms_contain() RETURNS trigger
    LANGUAGE plpgsql
AS $$
BEGIN
    IF TG_OP = 'DELETE' THEN
        RAISE EXCEPTION 'containment cannot be deleted' USING ERRCODE = '55000', CONSTRAINT = 'ck_qms_contain_no_delete';
    END IF;
    IF TG_OP = 'INSERT' THEN
        IF NEW.status <> 'OPEN' THEN
            RAISE EXCEPTION 'new containment must be OPEN' USING ERRCODE = '55000', CONSTRAINT = 'ck_qms_contain_open';
        END IF;
        IF NOT EXISTS (SELECT 1 FROM mst_item i WHERE i.item_id = NEW.item_id AND i.comp_cd = NEW.comp_cd) THEN
            RAISE EXCEPTION 'item % does not belong to company %', NEW.item_id, NEW.comp_cd USING ERRCODE = '23503', CONSTRAINT = 'fk_qms_contain_item_comp';
        END IF;
        IF NEW.ncr_id IS NOT NULL
           AND NOT EXISTS (SELECT 1 FROM qms_ncr n WHERE n.ncr_id = NEW.ncr_id AND n.comp_cd = NEW.comp_cd AND n.item_id = NEW.item_id) THEN
            RAISE EXCEPTION 'NCR % must be of the same company and item', NEW.ncr_id USING ERRCODE = '23514', CONSTRAINT = 'ck_qms_contain_ncr';
        END IF;
        RETURN NEW;
    END IF;
    -- UPDATE: OPEN → CLOSED 만, 그 밖 칸 고정
    IF (NEW.comp_cd, NEW.contain_no, NEW.item_id, NEW.ncr_id, NEW.from_date, NEW.to_date, NEW.reason, NEW.lot_cnt, NEW.created_at, NEW.created_by)
       IS DISTINCT FROM (OLD.comp_cd, OLD.contain_no, OLD.item_id, OLD.ncr_id, OLD.from_date, OLD.to_date, OLD.reason, OLD.lot_cnt, OLD.created_at,
                         OLD.created_by)
       OR OLD.status = 'CLOSED' OR NEW.status <> 'CLOSED' THEN
        RAISE EXCEPTION 'containment % can only be closed', OLD.contain_id USING ERRCODE = '55000', CONSTRAINT = 'ck_qms_contain_immutable';
    END IF;
    IF EXISTS (SELECT 1 FROM qms_contain_lot c WHERE c.contain_id = NEW.contain_id AND c.released_at IS NULL) THEN
        RAISE EXCEPTION 'containment % still has held lots', OLD.contain_id USING ERRCODE = '23514', CONSTRAINT = 'ck_qms_contain_all_released';
    END IF;
    RETURN NEW;
END
$$;
CREATE TRIGGER tg_qms_contain_guard BEFORE INSERT OR UPDATE OR DELETE ON qms_contain FOR EACH ROW EXECUTE FUNCTION hb_guard_qms_contain();
CREATE TRIGGER tg_audit AFTER INSERT OR UPDATE OR DELETE ON qms_contain FOR EACH ROW EXECUTE FUNCTION hb_audit('contain_id', '', '');

ALTER TABLE qms_contain ENABLE ROW LEVEL SECURITY;
ALTER TABLE qms_contain FORCE  ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON qms_contain USING (comp_cd = hb_current_comp()) WITH CHECK (comp_cd = hb_current_comp());
REVOKE DELETE, TRUNCATE ON qms_contain FROM ${app_role};

CREATE TABLE qms_contain_lot (
    contain_lot_id  bigint        GENERATED ALWAYS AS IDENTITY,
    comp_cd         varchar(20)   NOT NULL,
    contain_id      bigint        NOT NULL,
    lot_id          bigint        NOT NULL,
    released_at     timestamptz,
    released_by     varchar(50),
    release_reason  varchar(500),
    created_at      timestamptz   NOT NULL DEFAULT now(),
    created_by      varchar(50)   NOT NULL,
    CONSTRAINT pk_qms_contain_lot PRIMARY KEY (contain_lot_id),
    CONSTRAINT fk_qms_contain_lot_comp FOREIGN KEY (comp_cd) REFERENCES sys_comp (comp_cd),
    CONSTRAINT fk_qms_contain_lot_contain FOREIGN KEY (contain_id) REFERENCES qms_contain (contain_id),
    CONSTRAINT fk_qms_contain_lot_lot FOREIGN KEY (lot_id) REFERENCES lot_master (lot_id),
    CONSTRAINT uq_qms_contain_lot UNIQUE (contain_id, lot_id),
    CONSTRAINT ck_qms_contain_lot_release CHECK (
        (released_at IS NULL AND released_by IS NULL AND release_reason IS NULL)
        OR (released_at IS NOT NULL AND released_by IS NOT NULL AND release_reason IS NOT NULL AND length(btrim(release_reason)) > 0))
);
CREATE INDEX ix_qms_contain_lot_lot ON qms_contain_lot (comp_cd, lot_id);
COMMENT ON TABLE qms_contain_lot IS '봉쇄 LOT — 해제는 한 번만(시각·사람·사유), 삭제 금지 (docs/29_P3 Q8b)';

CREATE FUNCTION hb_guard_qms_contain_lot() RETURNS trigger
    LANGUAGE plpgsql
AS $$
DECLARE
    v_c qms_contain;
BEGIN
    IF TG_OP = 'DELETE' THEN
        RAISE EXCEPTION 'contained lot cannot be deleted (release it)' USING ERRCODE = '55000', CONSTRAINT = 'ck_qms_contain_lot_no_delete';
    END IF;
    IF TG_OP = 'INSERT' THEN
        SELECT * INTO v_c FROM qms_contain WHERE contain_id = NEW.contain_id AND comp_cd = NEW.comp_cd;
        IF NOT FOUND OR v_c.status <> 'OPEN' THEN
            RAISE EXCEPTION 'containment % is not open in company %', NEW.contain_id, NEW.comp_cd USING ERRCODE = '55000', CONSTRAINT = 'ck_qms_contain_lot_open';
        END IF;
        -- 잠금 없이 읽기(LOT 은 포트가 이미 잠갔다)
        IF NOT EXISTS (SELECT 1 FROM lot_master l WHERE l.lot_id = NEW.lot_id AND l.comp_cd = NEW.comp_cd AND l.item_id = v_c.item_id) THEN
            RAISE EXCEPTION 'lot % must be of the same company and item', NEW.lot_id USING ERRCODE = '23514', CONSTRAINT = 'ck_qms_contain_lot_item';
        END IF;
        IF NEW.released_at IS NOT NULL THEN
            RAISE EXCEPTION 'new contained lot must be held' USING ERRCODE = '55000', CONSTRAINT = 'ck_qms_contain_lot_held';
        END IF;
        RETURN NEW;
    END IF;
    -- UPDATE: 해제 칸을 한 번만 채운다
    IF (NEW.comp_cd, NEW.contain_id, NEW.lot_id, NEW.created_at, NEW.created_by) IS DISTINCT FROM
       (OLD.comp_cd, OLD.contain_id, OLD.lot_id, OLD.created_at, OLD.created_by)
       OR OLD.released_at IS NOT NULL OR NEW.released_at IS NULL THEN
        RAISE EXCEPTION 'contained lot % can only be released once', OLD.contain_lot_id USING ERRCODE = '55000', CONSTRAINT = 'ck_qms_contain_lot_immutable';
    END IF;
    RETURN NEW;
END
$$;
CREATE TRIGGER tg_qms_contain_lot_guard BEFORE INSERT OR UPDATE OR DELETE ON qms_contain_lot FOR EACH ROW EXECUTE FUNCTION hb_guard_qms_contain_lot();
CREATE TRIGGER tg_audit AFTER INSERT OR UPDATE OR DELETE ON qms_contain_lot FOR EACH ROW EXECUTE FUNCTION hb_audit('contain_lot_id', '', '');

ALTER TABLE qms_contain_lot ENABLE ROW LEVEL SECURITY;
ALTER TABLE qms_contain_lot FORCE  ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON qms_contain_lot USING (comp_cd = hb_current_comp()) WITH CHECK (comp_cd = hb_current_comp());
REVOKE DELETE, TRUNCATE ON qms_contain_lot FROM ${app_role};

-- 후보 조회는 MES 인덱스 ix_lot_master_item(comp_cd, item_id, created_at)로 품목을 좁힌다 — 남의 표에 인덱스를 더하지 않는다

INSERT INTO sys_prog (prog_cd, prog_nm_key, view_path, module_cd, actions, sort_no) VALUES
    ('qms-contain', 'prog.qmsContain', 'qms/contain', 'QMS', ARRAY['SEARCH','SAVE']::varchar(20)[], 698);
INSERT INTO sys_retention_table (table_nm, class_cd) VALUES ('qms_contain', 'QUALITY_RECORD'), ('qms_contain_lot', 'QUALITY_RECORD');
